text:
Caveman mode: **full**

---

Three parts: class component, fallback UI, usage.

```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null };

  static getDerivedStateFromError(error: Error): State {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    const { onError } = this.props;

    // Log details
    console.error("[ErrorBoundary] Caught error:", {
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
      timestamp: new Date().toISOString(),
    });

    onError?.(error, info);
  }

  reset = () => this.setState({ error: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    // Custom fallback wins
    if (fallback) return fallback(error, this.reset);

    return <DefaultFallback error={error} reset={this.reset} />;
  }
}
```

```tsx
// DefaultFallback.tsx
interface FallbackProps {
  error: Error;
  reset: () => void;
}

function DefaultFallback({ error, reset }: FallbackProps) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.title}>Something went wrong</h2>
      <pre style={styles.message}>{error.message}</pre>
      <button onClick={reset} style={styles.button}>
        Try again
      </button>
    </div>
  );
}

const styles = {
  container: {
    padding: "2rem",
    border: "1px solid #f87171",
    borderRadius: "8px",
    background: "#fef2f2",
    fontFamily: "sans-serif",
    maxWidth: "480px",
    margin: "2rem auto",
  },
  title:  { color: "#b91c1c", marginTop: 0 },
  message: { color: "#7f1d1d", fontSize: "0.875rem", whiteSpace: "pre-wrap" as const },
  button: {
    marginTop: "1rem",
    padding: "0.5rem 1.25rem",
    background: "#dc2626",
    color: "#fff",
    border: "none",
    borderRadius: "6px",
    cursor: "pointer",
    fontSize: "0.9rem",
  },
} as const;
```

```tsx
// Usage
import { ErrorBoundary } from "./ErrorBoundary";

// Basic — default fallback
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback
<ErrorBoundary
  fallback={(error, reset) => (
    <div>
      <p>Oops: {error.message}</p>
      <button onClick={reset}>Retry</button>
    </div>
  )}
  onError={(error, info) => sendToSentry(error, info)}  // hook into external logger
>
  <MyComponent />
</ErrorBoundary>
```

---

**Key decisions:**

- `getDerivedStateFromError` — static, pure, sets state for render. `componentDidCatch` — side effects (logging) only. Two jobs, two methods.
- `reset` clears `error` state → children re-mount fresh. If same bug still exist, boundary catch again.
- `onError` prop = escape hatch for Sentry/Datadog/custom logger. No coupling inside boundary.
- Custom `fallback` render prop beats default. Full control, no style fight.

**Caveat:** Boundaries no catch errors in: event handlers, async code (`setTimeout`/`fetch`), SSR. Those need `try/catch` direct.
